  coverage: 0.7,              // auto sizing: share of the annual consumption the PV should produce
  max_kwp: 100,
  losses: 0.14, inverter_kw: 0,
  annual_kwh: 4000, profile: 'habitatge',
  tariff: '2.0TD',
  prices: null,               // { "P1": 0.20, ... } or "0.20,0.14,0.09"
  compensation_price: 0.06, compensation_mode: 'simplificada', taxes: 0,
  pv_cost: 0, pv_cost_per_kwp: 1250, subsidy: 0, maintenance: 30,
  inflation: 0.02, degradation: 0.005, years: 25,
  battery_kwh: 0, battery_kw: 0, battery_cost: 0, battery_life: 12,
