// ---------- input files ----------
function inputFiles() {
  let dids = [];
  try { dids = JSON.parse(process.env.DIDS || '[]') || []; } catch (e) { dids = []; }
  const roots = dids.length ? dids.map(d => path.join(INPUTS, d)) : [INPUTS];
  const files = [];
  const walk = p => {
    if (!fs.existsSync(p)) return;
    const st = fs.statSync(p);
    if (st.isFile()) { if (path.basename(p) !== CUSTOM) files.push(p); return; }
    for (const f of fs.readdirSync(p).sort()) walk(path.join(p, f));
  };
  roots.forEach(walk);
  return files;
}

